const TAB_KEYS=['currentWorkspace','staffSession','selectedStaffId'];
function applyTabView(s){if(tabView){s.currentWorkspace=tabView.currentWorkspace;s.staffSession=tabView.staffSession;s.selectedStaffId=tabView.selectedStaffId}return s}
function loadState(){const s=applyTabView(storeLoad());if(tabView)return s;const product=document.body.dataset.product,p=PRODUCTS[product],selected=sessionStorage.getItem(`moveai-workspace-${product}`);if(p)s.currentWorkspace=p.roles.includes(selected)?selected:p.roles.includes(s.currentWorkspace)?s.currentWorkspace:p.defaultWs;return s}
function saveState(s){if(tabView){const shared=storeLoad();const out={...s};TAB_KEYS.forEach(k=>{out[k]=shared[k]});tabView={currentWorkspace:s.currentWorkspace,staffSession:s.staffSession,selectedStaffId:s.selectedStaffId};sessionStorage.setItem('moveai-tab-view',JSON.stringify(tabView));storeSave(out)}else{const product=document.body.dataset.product;if(PRODUCTS[product]?.roles.includes(s.currentWorkspace)){sessionStorage.setItem(`moveai-workspace-${product}`,s.currentWorkspace);storeSave({...s,currentWorkspace:storeLoad().currentWorkspace})}else storeSave(s)}}
function leaveTabView(){tabView=null;sessionStorage.removeItem('moveai-tab-view')}
function resetState(){leaveTabView();const product=document.body.dataset.product,s=storeReset();sessionStorage.removeItem(`moveai-workspace-${product}`);s.currentWorkspace=PRODUCTS[product]?.defaultWs||'personal';return s}
