function navButton(route,label,badge=0,mobile=false){return `<button type="button" class="nav-button" data-route="${route}" aria-label="${label}"><span class="nav-icon" aria-hidden="true">${ICONS[route]||'□'}</span><span class="nav-label">${label}</span>${badge&&!mobile?`<span class="nav-badge">${badge}</span>`:''}</button>`}
function roleForWorkspace(key){const base0=ROLE_CONFIG[key]||ROLE_CONFIG.personal;const base=key==='personal'?{...base0,...(PERSONAL_LABEL[activeProduct]||{}),nav:navFor('personal')}:base0;const override=state.workspaceOverrides?.[key];return override?{...base,...override}:base}
