const OPS_ROUTES={book:'bookScreen',bookingReview:'bookingReviewScreen',services:'servicesScreen',serviceDetail:'serviceDetailScreen',trips:'tripsScreen',tripDetail:'tripDetailScreen',assignTrip:'assignTripScreen',vehicleOffer:'vehicleOfferScreen',vehicleDetail:'vehicleDetailScreen',addVehicle:'addVehicleScreen',movingJob:'movingJobScreen',myJobs:'myJobsScreen',driverJob:'driverJobScreen',upgradeDriver:'upgradeDriverScreen',conversation:'conversationScreen',payment:'paymentFormScreen',paymentDetail:'paymentDetailScreen',exceptions:'exceptionsScreen',exceptionDetail:'exceptionDetailScreen',verification:'verificationScreen',verificationItem:'verificationItemScreen',cases:'casesScreen',staffEvents:'staffEventsScreen',notifications:'notificationsScreen'};
function opsRoute(route){
  const ws=state.currentWorkspace;
  if(route==='notifications')return NC.screen(state);
  {const hrScreen=HR.screen(state,route,ws);if(hrScreen)return hrScreen}
  {const pcScreen=PC.screen(state,route,ws);if(pcScreen)return pcScreen}
  {const lcScreen=LC.screen(state,route,ws);if(lcScreen)return lcScreen}
  {const hubScreen=Hub.screen(state,route,ws);if(hubScreen)return hubScreen}
  {const easyScreen=Easy.screen(state,route,ws);if(easyScreen)return easyScreen}
  if(route==='trips'&&!['personal','admin'].includes(ws)){const al=GP.ewbAlerts(state,OPS.opsCtx(state).ownerWs);if(al.length)return `<div class="action-warning ewb-alerts"><b>E-way bills need attention</b><span>${al.map(a=>`${a.t.id}: ${OPS.esc(a.s.label)}`).join(' · ')}</span><button class="button secondary compact" data-route="ewayBills">Open e-way bills</button></div>`+OPS.tripsScreen(state)}
  if(route==='myJobs'&&['commercialDriver','helper'].includes(ws)){const al=GP.ewbAlerts(state,ws).filter(a=>a.s.status!=='missing');if(al.length)return `<div class="action-warning"><b>E-way bill</b><span>${al.map(a=>`${a.t.id}: ${OPS.esc(a.s.label)}`).join(' · ')}. Tell your transporter before driving on.</span></div>`+OPS.myJobsScreen(state)}
  if(OPS_ROUTES[route])return OPS[OPS_ROUTES[route]](state);
  if(ws==='personal'&&route==='home'){if(activeProduct==='customer')return customerHomeScreen(state);if(activeProduct==='partner')return WO.currentCandidate(state)?WO.workerStatusScreen(state):WO.workerDetailsScreen(state);if(activeProduct==='business'){const a=state.businessApplications.find(x=>x.ownerId===state.person?.id);if(a){currentApplication();return applicationStatusScreen(state)+draftPanel(state,a)}return businessStartScreen(state)}}
  if(route==='applicationStatus'&&ws==='personal'){const a=currentApplication();return applicationStatusScreen(state)+draftPanel(state,a)}
  if(route==='account')return accountScreen(state);
  const plusScreen=Plus.screen(state,route,ws);if(plusScreen)return plusScreen;
  if(route==='shopTeam'){const sh=Commerce.screen(state,route,ws);if(sh)return `<div class="info-banner"><b>Branches and cover assignments are in People & pay</b><span>Pay, advances and balances now live on each person's own "Pay" button below, not here.</span><button class="button primary compact" data-route="storeHR">Open People & pay</button></div>`+sh}
  const shop=Commerce.screen(state,route,ws);if(shop)return route==='deliveryJobs'?shop+Plus.deliveryExtras(state,ws):shop;
  if(route==='productCheckout'&&ws==='personal')return PO.checkoutScreen(state);
  if(route==='productDetail'&&ws==='personal')return PO.productDetailScreen(state);
  if(route==='cartAdded'&&ws==='personal')return PO.cartAddedScreen(state);
  if(route==='cart'&&ws==='personal')return PO.cartScreen(state);
  if(route==='orderTracking'&&ws==='personal')return PO.trackingScreen(state);
  if(route==='search'&&ws==='personal')return PO.searchScreen(state);
  if(route==='orders'&&ws==='personal')return PO.ordersScreen(state);
  if(route==='money'&&ws==='personal')return CB.customerPaymentsScreen(state,Pay.paySummary);
  if(route==='billDoc'&&ws==='personal')return CB.docScreen(state);
  if(route==='inviteSent')return SJ.inviteSentScreen(state)||'';
  if(route==='payOps')return Pay.payOpsScreen(state);
  if(route==='pricingRules')return Pay.pricingRulesScreen(state);
  if(route==='ewayBills')return GP.ewbListScreen(state);
  if(route==='tripSettlement'&&!['personal','admin'].includes(ws))return WF.tripSettlementScreen(state)+FR.fuelCardHtml(state);
  if(route==='invoices')return FR.invoicesScreen(state);if(route==='invoiceNew')return FR.invoiceNewScreen(state);if(route==='invoiceDetail')return FR.invoiceDetailScreen(state);
  if(route==='money'&&['movers','personalDriver'].includes(ws))return Pay.walletPanel(state,ws)+OPS.moneyScreen(state);
  if(route==='workforce')return WF.workforceScreen(state);
  if(route==='offboarding'&&['goods','transporter','vehicle','movers'].includes(ws))return offboardingScreen(state)+WF.exitSettlementPanel(state);if(route==='dutyBoard')return WF.dutyBoardScreen(state);if(route==='payroll')return WF.payrollScreen(state);if(route==='khata')return WF.khataScreen(state);if(route==='tripSettlement')return WF.tripSettlementScreen(state);
  if(route==='money'&&['staff','commercialDriver','helper'].includes(ws)){const k=WF.selfKhataPanel(state),w=ws==='staff'?'':Pay.walletPanel(state,ws),ack=LC.ackPanel(state,ws);if(k||w||ack)return ack+k+w+OPS.moneyScreen(state)}
  const workerWs=['commercialDriver','personalDriver','helper'].includes(ws);
  if(route==='workerDocuments')return WO.workerDocumentsScreen(state);
  if(route==='workerStatus')return WO.workerStatusScreen(state);
  if(route==='workerVerify')return WO.workerVerifyScreen(state);
  if(route==='candidateProfile'||(route==='profile'&&workerWs))return WO.workerDetailsScreen(state);
  if(route==='work'&&(workerWs||ws==='personal')){const c=WO.currentCandidate(state);if(!c)return WO.workGateScreen(state,null,'Tell us what work you want to see jobs near you.');return WO.workGateBanner(c)+candidateWorkScreen(state)}
  if(route==='fleet'&&['goods','transporter','vehicle','movers'].includes(ws))return OPS.fleetScreen(state);
  if(route==='fleet'&&ws==='staff')return OPS.can(state,'fleet.manage')?OPS.fleetScreen(state):deniedScreen();
  if(route==='work'&&ws==='staff'&&selectedStaff()?.status==='active')return OPS.staffWorkScreen(state);
  if(route==='messages')return OPS.messagesScreen(state);
  if(route==='money')return OPS.moneyScreen(state);
  if(route==='work'&&ws==='movers')return OPS.movingQueueScreen(state);
  return '';
}
const opsApi={getState:()=>state,save:()=>saveState(state),render:()=>{renderRoute();renderBell()},toast:m=>toast(m),navigate:r=>{if(readRoute()===r)renderRoute();else navigate(r);renderBell()}};
function unreadCount(){const ws=state.currentWorkspace,key=ws==='staff'?`staff:${state.selectedStaffId}`:ws;return NC.badge(state,(state.notifications||[]).filter(n=>(n.to===ws||n.to===key||(n.parties||[]).includes(ws))&&(!n.pickerId||n.pickerId===currentPicker(state,ws)?.id)&&(!n.managerId||n.managerId===GroceryWorkforce.activeManager(state,ws)?.id)&&!n.read),ws)}
