function assistantRun(text){if(!text.trim())return;const r=runAssistant(state,text),box=$('ai-readback');aiPending=null;$('ai-confirm').hidden=true;
  if(r.answer){box.innerHTML=`<p><b>Heard:</b> “${OPS.esc(text)}”</p><p>${OPS.esc(r.answer)}</p>`;return}
  if(r.intent==='note'||r.intent==='unknown'){box.innerHTML=`<p><b>Heard:</b> “${OPS.esc(text)}”</p><p>I could not match this to an action. Try “summarize TRP-501”, a payment, a milestone or an exception.</p>`;return}
  if(r.intent==='work_profile'){state.workerTypeDraft=r.fields.workerType;state.workerLocationDraft=r.fields.city;saveState(state);box.innerHTML=`<p><b>Heard:</b> “${OPS.esc(text)}”</p><p>${OPS.esc(r.readBack)}</p>`;if(state.currentWorkspace!=='personal'){box.innerHTML+='<p class="muted">Switch to your personal account to start a work profile.</p>';return}if(!WO.currentCandidate(state))navigate('candidateProfile');return}
  if(r.intent==='fill_moving'||r.intent==='fill_driver'){state.bookingDraft={service:r.intent==='fill_moving'?'moving':'driver',...Object.fromEntries(Object.entries(r.fields||{}).filter(([,v])=>v)),description:text,voiceNote:`Heard: “${text}” — ${r.readBack}`};saveState(state);box.innerHTML=`<p>${OPS.esc(r.readBack)}</p><p class="muted">Opening the booking form so you can check it.</p>`;if(state.currentWorkspace==='personal')navigate('book');return}
  aiPending=r;box.innerHTML=`<p><b>Heard:</b> “${OPS.esc(text)}”</p><p class="attention"><b>Please confirm:</b> ${OPS.esc(r.readBack||'Run this action?')}</p><p class="muted">Critical actions run only after you confirm. Payments are saved for approval.</p>`;$('ai-confirm').hidden=false}

