// Single always-on, lightweight poll for the Pay screen — checks a cheap counter (state.payVersion)
// rather than diffing the whole ledger, and only re-renders when it actually changed and the user is
// still sitting on a payroll-related screen. Within this one-browser prototype, confirming a payment
// on one side already updates shared state instantly; this just means you don't have to navigate away
// and back to see it. A real backend would swap this for an actual push/poll against the server —
// same pattern, different source of truth, so this isn't throwaway code for the eventual integration.
let __lastSeenPayVersion=state.payVersion||0;
setInterval(()=>{
  const v=state.payVersion||0;
  if(v!==__lastSeenPayVersion){__lastSeenPayVersion=v;if(['unifiedPay'].includes(state.currentRoute))renderRoute();}
},3500);

function renderAll(){renderWorkspace();renderDesktopNav();renderMobileNav();if(!location.hash)location.hash=state.auth?.status==='authenticated'?'#/home':'#/welcome';renderRoute();app.setAttribute('aria-busy','false')}
renderAll();

window.addEventListener('storage',e=>{if(!e.key||!e.key.startsWith('moveai')||e.key==='moveai-tab-view'||e.key.startsWith('moveai-workspace-'))return;state=loadState();const r=readRoute();if(document.body.classList.contains('join-mode')||['people','staffDetail','inviteSent','notifications','home','search','cart','orders','orderTracking','shopOrders','shopIssues','shopTeam','shopSchedule','shopOffboarding','managerTimecards','managerProfile','shopPickerPay','shopCatalog','shopCounter','shopCounterDelivery','shopSales','shopEarnings','pickTasks','pickSchedule','pickEarnings','pickProfile','deliveryJobs','deliveryCash','deliveryEarnings','commerceOps','commerceOrders','commercePartners','commercePayments','commerceIssues'].includes(r)){syncingFromStorage=true;try{renderWorkspace();renderDesktopNav();renderMobileNav();renderRoute()}finally{syncingFromStorage=false}}});
window.MoveAIVNextTest={state:()=>structuredClone(state),switchWorkspace,product:()=>activeProduct,canOpen,reset:()=>{state=resetState();renderAll()},startSignup:()=>{state=signupDemoState();saveState(state);navigate('welcome')},routes:()=>Object.keys(ROUTES)};
